                            /** @enum {string} */
                            type: "AUTOMATED_CANCELED" | "AUTOMATED_NEW_FOLLOWER" | "AUTOMATED_NEW_PURCHASE" | "AUTOMATED_NEW_SUBSCRIBER" | "AUTOMATED_RE_SUBSCRIBED" | "AUTOMATED_RENEWED" | "AUTOMATED_CHAT_MESSAGE_REPLY" | "AUTOMATED_FIRST_MESSAGE_REPLY" | "CHAT_TEXT_GENERATION" | "CHAT_TEXT_REPLY" | "CHAT_TEXT_REWRITE" | "SINGLE_RECIPIENT" | "TIP" | "VOICE_CALL" | "BROADCAST" | "GHOST_PROMOTION";
                            /** @description Pricing information for pay-to-view messages */
