    createCreatorUploadSession: {
        parameters: {
            query?: never;
            header: {
                /** @description API version to use for the request */
                "X-Fanvue-API-Version": components["parameters"]["ApiVersionHeader"];
            };
            path: {
                creatorUserUuid: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    name: string;
                    filename: string;
                    /** @enum {string} */
                    mediaType: "image" | "video" | "audio" | "document";
                    /** @description Total size of the file in bytes. When provided, the response includes the exact `totalParts` to upload. */
                    sizeBytes?: number;
                };
            };
        };
        responses: {
            /** @description Upload session created */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "mediaUuid": "d4e5f6a7-8b9c-0d1e-2f3a-4b5c6d7e8f9a",
                     *       "uploadId": "abc123XYZ789multipart",
                     *       "partSize": 6291456,
                     *       "maxParts": 854,
                     *       "totalParts": 4
                     *     }
                     */
                    "application/json": {
                        /** Format: uuid */
                        mediaUuid: string;
                        uploadId: string;
                        /** @description Size in bytes of every part except the final one (which may be smaller). */
                        partSize: number;
                        /** @description Maximum number of parts allowed, derived from the maximum supported file size. */
                        maxParts: number;
                        /** @description Exact number of parts to upload, computed from `sizeBytes`. Null when `sizeBytes` was not provided — compute it client-side as ceil(fileSize / partSize). */
                        totalParts: number | null;
                    };
                };
            };
            401: components["responses"]["UnauthorizedResponse"];
            403: components["responses"]["UnauthorizedResponse"];
            404: components["responses"]["NotFoundResponse"];
            410: components["responses"]["SunsetVersionResponse"];
            429: components["responses"]["RateLimitResponse"];
        };
    };
