    getExperienceActionPurchase: {
        parameters: {
            query?: never;
            header: {
                /** @description API version to use for the request */
                "X-Fanvue-API-Version": components["parameters"]["ApiVersionHeader"];
            };
            path: {
                experienceUuid: string;
                purchaseReference: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The action purchase */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "purchaseReference": "expact_5c9a1f0e-9f3f-4c2a-8f31-1d0f6a2b7c44",
                     *       "experienceUuid": "00000000-0000-4000-8000-000000000010",
                     *       "externalActionId": "spin",
                     *       "clientReferenceId": "round-42",
                     *       "buyerUuid": "00000000-0000-4000-8000-000000000003",
                     *       "amount": 700,
                     *       "currency": "USD",
                     *       "status": "succeeded",
                     *       "invoiceNumber": "FVE-20260904-1234",
                     *       "createdAt": "2026-09-04T10:00:00.000Z",
                     *       "paidAt": "2026-09-04T10:00:02.000Z"
                     *     }
                     */
                    "application/json": {
                        /**
                         * @description The `expact_…` reference minted with the purchase attempt. THE fulfilment idempotency key: grant the action at most once per reference, and only for a purchase whose status is `succeeded`.
                         * @example expact_5c9a1f0e-9f3f-4c2a-8f31-1d0f6a2b7c44
                         */
                        purchaseReference: string;
                        /**
                         * Format: uuid
                         * @description The experience the action belongs to.
                         * @example 00000000-0000-4000-8000-000000000010
                         */
                        experienceUuid: string;
                        /**
                         * @description The app's own stable key for the action that was bought.
                         * @example spin
                         */
                        externalActionId: string;
                        /**
                         * @description The app-supplied reference carried through the purchase, or null when the app supplied none.
                         * @example round-42
                         */
                        clientReferenceId: string | null;
                        /**
                         * Format: uuid
                         * @description UUID of the fan who bought the action. The only identifier of the buyer this surface carries — no handle, no display name, no email.
                         * @example 00000000-0000-4000-8000-000000000003
                         */
                        buyerUuid: string;
                        /**
                         * @description Price in minor currency units (cents), frozen at the purchase attempt. A later re-pricing of the action does not move it.
                         * @example 700
                         */
                        amount: number;
                        /**
                         * @description ISO 4217 code of the amount. USD only today.
                         * @example USD
                         */
                        currency: string;
                        /**
                         * @description Where the money for this purchase attempt ended up. Fulfil only on `succeeded`. `refunded`, `disputed` and `cancelled` all mean the money is not the creator's, so revoke on any of them — the difference between them only records how the reversal was written, not whether to act. `refunded` is a reversal carrying a refund reference (a settled payment paid back, or an authorisation voided before capture); `disputed` is a chargeback that was lost and reversed; `cancelled` is a reversal carrying neither reference (a delayed capture that failed, or the uncaptured-invoice sweeper). An open dispute that has not been lost is still `succeeded` here — the money has not moved — so watch `app.experience.action.dispute.*` for that, not this field. A refund the processor accepted and then rejected also reports `succeeded` again: this field is where the money ended up, not what was attempted.
                         * @enum {string}
                         */
                        status: "pending" | "succeeded" | "failed" | "refunded" | "disputed" | "cancelled";
                        /**
                         * @description Fanvue invoice number for the charge. For support and accounting, not fulfilment.
                         * @example FVE-20260904-1234
                         */
                        invoiceNumber: string;
                        /**
                         * Format: date-time
                         * @description When the purchase attempt was opened.
                         * @example 2026-09-04T10:00:00.000Z
                         */
                        createdAt: string;
                        /**
                         * Format: date-time
                         * @description When the charge settled, or null while it has not.
                         * @example 2026-09-04T10:00:02.000Z
                         */
                        paidAt: string | null;
                    };
                };
            };
            /** @description Bad Request - API version not supported OR validation failed OR invalid UUID */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["UnsupportedVersionError"] | components["schemas"]["ValidationError"] | components["schemas"]["InvalidUuidError"];
                };
            };
            401: components["responses"]["UnauthorizedResponse"];
            403: components["responses"]["UnauthorizedResponse"];
            /** @description Experience not found, or not owned by the calling app */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        message?: string;
                    };
                };
            };
            410: components["responses"]["SunsetVersionResponse"];
            429: components["responses"]["RateLimitResponse"];
            /** @description Failed to read the purchases from the upstream */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        message?: string;
                    };
                };
            };
            /** @description Developer API upstream is not configured */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        message?: string;
                    };
                };
            };
        };
    };
